// Map-window background restore of the original main loop (`$16012`), as a pure function over indexed pixels.
// Static trace of the local Disk.1 image, see notes/formats/map-rendering.md section 9. No original data is stored
// here: the 32x16 texture and the two bitmap snapshots are taken from the player's decoded main-screen picture, and the
// mask pattern is generated by the same state machine as `$15F9A`.
//
// The original runs `$16012` once per main-loop iteration against a back buffer. This port reproduces its pixel effect on
// a 320x200 indexed buffer (5 planes = colour index 0..31). Regions it does not write (row 88 of the window, the right
// 48 columns of the top bar, everything below row 159, ...) keep the pixels of the buffer it is given.

import { SCREEN_HEIGHT, SCREEN_WIDTH } from "../gfx/screen.js";

/** Texture strip copied by `$4E7E` from every plane at byte offset `$10`: x 128..159, rows 0..15 (`$16BB2`). */
export const TEXTURE_X = 128;
export const TEXTURE_WIDTH = 32;
export const TEXTURE_HEIGHT = 16;

/** Window width restored by the strip and pattern passes: 8 longs of 32 pixels (x 0..255). */
export const RESTORE_WIDTH = 256;

/** Region 1, rows 0..23: the texture with its vertical halves swapped. */
export const BAR_ROWS = 24;
/** Region 2, rows 24..87: four 16-row pattern layers (`$14640` + 0, `$200`, `$400`, `$600`). */
export const PATTERN_FIRST_ROW = 24;
export const PATTERN_LAYERS = 4;
export const PATTERN_LAYER_ROWS = 16;
/** Region 3, rows 89..159, x 0..255, copied from the snapshot at `$26372` (71 rows). Row 88 is never written. */
export const SNAPSHOT_FIRST_ROW = 89;
export const SNAPSHOT_LAST_ROW = 159;
/** Region 4, x 256..271, rows 47..96 (50 rows), copied from the snapshot at `$2617E`. */
export const COLUMN_X = 256;
export const COLUMN_WIDTH = 16;
export const COLUMN_FIRST_ROW = 47;
export const COLUMN_LAST_ROW = 96;

/** The pattern is 64 state vectors (32-byte entries) of 8 big-endian longs d0..d7, 0x800 bytes at `$14640`. */
export const PATTERN_ENTRIES = 64;
export const VECTOR_LONGS = 8;
/** `$15F9A` also stores every vector forwards at `$14E40`.. (63 vectors, up to `$1561F`); no code in this port reads it. */
export const TAIL_ENTRIES = 63;

export interface MapPattern {
  /** 64 x 8 longs. Entry 63 is all zero, entry 62 holds the first state, entry 0 the last (63rd) one. */
  readonly table: Uint32Array;
  /** 63 x 8 longs: the same states in generation order (state 0 first), the forward stores of `$15F9A`. */
  readonly tail: Uint32Array;
}

/**
 * Re-runs `$15F9A`. D0..D3 and D4..D7 are two 128-bit chains. Each of the 126 shift passes (two per stored state) does
 * `ASR.L #1,D0; ROXR.L #1,D1..D3` (arithmetic right shift of D0..D3, X = bit shifted out of the previous long), then
 * `ASL.L #1,D7; BSET #0,D7; ROXL.L #1,D6..D4` (left shift of D4..D7 with a 1 inserted at bit 0; the ASL's carry feeds
 * D6, the BSET leaves X alone). Start: D0 = $C0000000, D7 = 3, the rest 0.
 */
export function generateMapPattern(): MapPattern {
  const table = new Uint32Array(PATTERN_ENTRIES * VECTOR_LONGS); // entry 63 stays zero (the first `movem` at `$15FBA`)
  const tail = new Uint32Array(TAIL_ENTRIES * VECTOR_LONGS);
  const d = new Uint32Array(VECTOR_LONGS);
  d[0] = 0xc0000000;
  d[7] = 3;
  for (let step = 0; step < TAIL_ENTRIES; step++) {
    table.set(d, (TAIL_ENTRIES - 1 - step) * VECTOR_LONGS); // (a1), walking down from `$14E00`
    tail.set(d, step * VECTOR_LONGS); // (a0), walking up from `$14E40`
    for (let pass = 0; pass < 2; pass++) {
      let x = d[0] & 1;
      d[0] = ((d[0] >>> 1) | (d[0] & 0x80000000)) >>> 0; // ASR.L #1
      for (let i = 1; i <= 3; i++) { // ROXR.L #1
        const out = d[i] & 1;
        d[i] = ((d[i] >>> 1) | (x << 31)) >>> 0;
        x = out;
      }
      x = d[7] >>> 31; // ASL.L #1 sets X from the bit shifted out
      d[7] = ((d[7] << 1) | 1) >>> 0; // ... and BSET #0 follows
      for (let i = 6; i >= 4; i--) { // ROXL.L #1
        const out = d[i] >>> 31;
        d[i] = ((d[i] << 1) | x) >>> 0;
        x = out;
      }
    }
  }
  return { table, tail };
}

let cachedTable: Uint32Array | null = null;

/**
 * Pixel effect of `$16012`. `initial` is the freshly decoded main-screen picture (indexed, 320x200): the original takes
 * the texture (`$4E7E`) and both bitmap snapshots (`$5028`-`$507A`) from the screen buffer right after `$2B1A` has unpacked
 * the picture, so all three sources are `initial`. `current` is the buffer being restored (default: a copy of `initial`);
 * pixels the routine does not write keep its values. Neither input is modified; a new buffer is returned.
 */
export function restoreMapBackground(initial: Uint8Array, current: Uint8Array = initial): Uint8Array {
  const size = SCREEN_WIDTH * SCREEN_HEIGHT;
  if (initial.length !== size || current.length !== size) {
    throw new Error(`restoreMapBackground: expected ${size} indexed pixels (${SCREEN_WIDTH}x${SCREEN_HEIGHT})`);
  }
  cachedTable ??= generateMapPattern().table;
  const pattern = cachedTable;
  const out = current.slice();

  const texture = new Uint8Array(TEXTURE_WIDTH * TEXTURE_HEIGHT);
  for (let y = 0; y < TEXTURE_HEIGHT; y++) {
    for (let x = 0; x < TEXTURE_WIDTH; x++) texture[y * TEXTURE_WIDTH + x] = initial[y * SCREEN_WIDTH + TEXTURE_X + x];
  }

  // Region 1: for source rows s = 0..7, destination s and s+16 take texture row s+8, destination s+8 takes row s.
  for (let s = 0; s < 8; s++) {
    for (const [dest, src] of [[s, s + 8], [s + 8, s], [s + 16, s + 8]] as const) {
      for (let x = 0; x < RESTORE_WIDTH; x++) out[dest * SCREEN_WIDTH + x] = texture[src * TEXTURE_WIDTH + (x & 31)];
    }
  }

  // Region 2: texture row r tiled eight times, kept only where the pattern bit (MSB = leftmost pixel) is set.
  for (let layer = 0; layer < PATTERN_LAYERS; layer++) {
    for (let r = 0; r < PATTERN_LAYER_ROWS; r++) {
      const row = PATTERN_FIRST_ROW + layer * PATTERN_LAYER_ROWS + r;
      const entry = (layer * PATTERN_LAYER_ROWS + r) * VECTOR_LONGS;
      for (let x = 0; x < RESTORE_WIDTH; x++) {
        const bit = (pattern[entry + (x >> 5)] >>> (31 - (x & 31))) & 1;
        out[row * SCREEN_WIDTH + x] = bit ? texture[r * TEXTURE_WIDTH + (x & 31)] : 0;
      }
    }
  }

  // Region 3: rows 89..159, x 0..255 from the saved initial bitmap (row 88 is skipped).
  for (let y = SNAPSHOT_FIRST_ROW; y <= SNAPSHOT_LAST_ROW; y++) {
    const at = y * SCREEN_WIDTH;
    for (let x = 0; x < RESTORE_WIDTH; x++) out[at + x] = initial[at + x];
  }

  // Region 4: x 256..271, rows 47..96 from its own snapshot.
  for (let y = COLUMN_FIRST_ROW; y <= COLUMN_LAST_ROW; y++) {
    const at = y * SCREEN_WIDTH + COLUMN_X;
    for (let x = 0; x < COLUMN_WIDTH; x++) out[at + x] = initial[at + x];
  }
  return out;
}
